using System.Data;
using System.Text.Json;
using Ams.Application.Abstractions.Persistence;
using Dapper;

namespace Ams.Worker.Intelligence;

public sealed class IntelligenceWorkerProcessor(ISqlConnectionFactory connectionFactory,ILogger<IntelligenceWorkerProcessor> logger)
{
    public async Task<IntelligenceWorkerSettings> GetSettingsAsync(CancellationToken cancellationToken)
    {
        const string sql="""SELECT SettingKey,COALESCE(SettingValue,DefaultValue) SettingValue FROM Core.ConfigurationSetting WHERE TenantId IS NULL AND ScopeCode=N'Platform' AND ModuleCode=N'Intelligence' AND IsDeleted=0;""";using var connection=await connectionFactory.CreateOpenConnectionAsync(cancellationToken);var values=(await connection.QueryAsync<SettingRow>(new CommandDefinition(sql,cancellationToken:cancellationToken))).ToDictionary(x=>x.SettingKey,x=>x.SettingValue,StringComparer.OrdinalIgnoreCase);int Read(string key,int fallback)=>int.TryParse(values.GetValueOrDefault(key),out var value)?value:fallback;return new(Math.Clamp(Read("Intelligence.Recommendation.WorkerBatchSize",20),1,100),Math.Clamp(Read("Intelligence.Recommendation.WorkerIntervalSeconds",10),1,300),Math.Clamp(Read("Intelligence.Recommendation.LeaseSeconds",300),30,1800),Math.Clamp(Read("Intelligence.Evaluation.WorkerIntervalMinutes",15),1,1440),Math.Clamp(Read("Intelligence.Search.IndexIntervalMinutes",10),1,1440));
    }

    public async Task<int> SynchronizeSearchIndexAsync(CancellationToken cancellationToken)
    {
        const string sql="""
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @lockResult INT;
EXEC @lockResult=sys.sp_getapplock @Resource=N'AI.SearchPermission.Synchronize',@LockMode=N'Exclusive',@LockOwner=N'Transaction',@LockTimeout=0;
IF @lockResult<0 BEGIN ROLLBACK TRANSACTION; THROW 51000,'Intelligence search synchronization is already running.',1; END;
DECLARE @changed TABLE(SearchDocumentId UNIQUEIDENTIFIER);
MERGE AI.SearchDocument target USING(SELECT account.TenantId,N'ACCOUNT' EntityTypeCode,account.AccountId EntityId,N'Accounts' ModuleCode,account.AccountName Title,CONCAT_WS(N' ',account.AccountNumber,account.AccountName,account.AccountTypeCode,account.StatusCode,account.SegmentCode,account.LifecycleStageCode,account.Industry,account.MainEmail,account.MainPhone) ContentText,CONCAT_WS(N' ',account.Industry,account.SegmentCode,account.AccountTypeCode) Keywords,account.OwnerUserId PrincipalUserId,CONVERT(char(64),HASHBYTES('SHA2_256',CONCAT_WS(N'|',account.AccountNumber,account.AccountName,account.StatusCode,account.SegmentCode,account.Industry,account.ModifiedDateUtc)),2) ContentHash,COALESCE(account.ModifiedDateUtc,account.CreatedDateUtc) SourceModifiedDateUtc,account.CreatedDateUtc SourceCreatedDateUtc FROM Client.Account account WHERE account.IsDeleted=0) source ON target.TenantId=source.TenantId AND target.EntityTypeCode=source.EntityTypeCode AND target.EntityId=source.EntityId WHEN MATCHED AND (target.ContentHash<>source.ContentHash OR target.IsDeleted=1 OR target.SourceCreatedDateUtc IS NULL) THEN UPDATE SET ModuleCode=source.ModuleCode,Title=source.Title,ContentText=source.ContentText,Keywords=source.Keywords,ContentHash=source.ContentHash,IndexedDateUtc=SYSUTCDATETIME(),SourceModifiedDateUtc=source.SourceModifiedDateUtc,SourceCreatedDateUtc=source.SourceCreatedDateUtc,ModifiedDateUtc=SYSUTCDATETIME(),IsDeleted=0 WHEN NOT MATCHED THEN INSERT(TenantId,EntityTypeCode,EntityId,ModuleCode,Title,ContentText,Keywords,SecurityScopeJson,ContentHash,IndexedDateUtc,SourceModifiedDateUtc,SourceCreatedDateUtc,CreatedDateUtc,IsDeleted) VALUES(source.TenantId,source.EntityTypeCode,source.EntityId,source.ModuleCode,source.Title,source.ContentText,source.Keywords,N'{}',source.ContentHash,SYSUTCDATETIME(),source.SourceModifiedDateUtc,source.SourceCreatedDateUtc,SYSUTCDATETIME(),0) OUTPUT inserted.SearchDocumentId INTO @changed;
MERGE AI.SearchDocument target USING(SELECT submission.TenantId,N'SUBMISSION' EntityTypeCode,submission.SubmissionId EntityId,N'Submissions' ModuleCode,CONCAT(submission.SubmissionNumber,N' · ',account.AccountName) Title,CONCAT_WS(N' ',submission.SubmissionNumber,account.AccountName,submission.LineOfBusiness,submission.Status,submission.Priority) ContentText,CONCAT_WS(N' ',submission.LineOfBusiness,submission.Status,submission.Priority) Keywords,submission.AssignedToUserId PrincipalUserId,CONVERT(char(64),HASHBYTES('SHA2_256',CONCAT_WS(N'|',submission.SubmissionNumber,account.AccountName,submission.LineOfBusiness,submission.Status,submission.Priority,submission.ModifiedDateUtc)),2) ContentHash,COALESCE(submission.ModifiedDateUtc,submission.CreatedDateUtc) SourceModifiedDateUtc,submission.CreatedDateUtc SourceCreatedDateUtc FROM Submissions.Submission submission JOIN Client.Account account ON account.TenantId=submission.TenantId AND account.AccountId=submission.AccountId AND account.IsDeleted=0 WHERE submission.IsDeleted=0) source ON target.TenantId=source.TenantId AND target.EntityTypeCode=source.EntityTypeCode AND target.EntityId=source.EntityId WHEN MATCHED AND (target.ContentHash<>source.ContentHash OR target.IsDeleted=1 OR target.SourceCreatedDateUtc IS NULL) THEN UPDATE SET ModuleCode=source.ModuleCode,Title=source.Title,ContentText=source.ContentText,Keywords=source.Keywords,ContentHash=source.ContentHash,IndexedDateUtc=SYSUTCDATETIME(),SourceModifiedDateUtc=source.SourceModifiedDateUtc,SourceCreatedDateUtc=source.SourceCreatedDateUtc,ModifiedDateUtc=SYSUTCDATETIME(),IsDeleted=0 WHEN NOT MATCHED THEN INSERT(TenantId,EntityTypeCode,EntityId,ModuleCode,Title,ContentText,Keywords,SecurityScopeJson,ContentHash,IndexedDateUtc,SourceModifiedDateUtc,SourceCreatedDateUtc,CreatedDateUtc,IsDeleted) VALUES(source.TenantId,source.EntityTypeCode,source.EntityId,source.ModuleCode,source.Title,source.ContentText,source.Keywords,N'{}',source.ContentHash,SYSUTCDATETIME(),source.SourceModifiedDateUtc,source.SourceCreatedDateUtc,SYSUTCDATETIME(),0) OUTPUT inserted.SearchDocumentId INTO @changed;
MERGE AI.SearchDocument target USING(SELECT claim.TenantId,N'CLAIM' EntityTypeCode,claim.ClaimId EntityId,N'Claims' ModuleCode,CONCAT(claim.ClaimNumber,N' · ',claim.AccountName) Title,CONCAT_WS(N' ',claim.ClaimNumber,claim.PolicyNumber,claim.AccountName,claim.Lob,claim.Carrier,claim.Status,claim.LossType,claim.PrimaryClaimant,claim.LossDescription,claim.CauseOfLoss,claim.LossLocation,claim.StateOfLoss) ContentText,CONCAT_WS(N' ',claim.Lob,claim.Status,claim.LossType,claim.CauseOfLoss) Keywords,CAST(NULL AS UNIQUEIDENTIFIER) PrincipalUserId,CONVERT(char(64),HASHBYTES('SHA2_256',CONCAT_WS(N'|',claim.ClaimNumber,claim.Status,claim.TotalIncurred,claim.LossDescription,claim.ModifiedDateUtc)),2) ContentHash,COALESCE(claim.ModifiedDateUtc,claim.CreatedDateUtc) SourceModifiedDateUtc,claim.CreatedDateUtc SourceCreatedDateUtc FROM Claims.Claim claim WHERE claim.IsDeleted=0) source ON target.TenantId=source.TenantId AND target.EntityTypeCode=source.EntityTypeCode AND target.EntityId=source.EntityId WHEN MATCHED AND (target.ContentHash<>source.ContentHash OR target.IsDeleted=1 OR target.SourceCreatedDateUtc IS NULL) THEN UPDATE SET ModuleCode=source.ModuleCode,Title=source.Title,ContentText=source.ContentText,Keywords=source.Keywords,ContentHash=source.ContentHash,IndexedDateUtc=SYSUTCDATETIME(),SourceModifiedDateUtc=source.SourceModifiedDateUtc,SourceCreatedDateUtc=source.SourceCreatedDateUtc,ModifiedDateUtc=SYSUTCDATETIME(),IsDeleted=0 WHEN NOT MATCHED THEN INSERT(TenantId,EntityTypeCode,EntityId,ModuleCode,Title,ContentText,Keywords,SecurityScopeJson,ContentHash,IndexedDateUtc,SourceModifiedDateUtc,SourceCreatedDateUtc,CreatedDateUtc,IsDeleted) VALUES(source.TenantId,source.EntityTypeCode,source.EntityId,source.ModuleCode,source.Title,source.ContentText,source.Keywords,N'{}',source.ContentHash,SYSUTCDATETIME(),source.SourceModifiedDateUtc,source.SourceCreatedDateUtc,SYSUTCDATETIME(),0) OUTPUT inserted.SearchDocumentId INTO @changed;
MERGE AI.SearchDocument target USING(SELECT document.TenantId,N'DOCUMENT' EntityTypeCode,document.DocumentId EntityId,N'Documents' ModuleCode,document.FileName Title,CONCAT_WS(N' ',document.FileName,document.DocumentTypeCode,document.CategoryCode,document.EntityName,document.Description,document.Tags,document.StatusCode) ContentText,CONCAT_WS(N' ',document.DocumentTypeCode,document.CategoryCode,document.Tags) Keywords,document.CreatedByUserId PrincipalUserId,CONVERT(char(64),HASHBYTES('SHA2_256',CONCAT_WS(N'|',document.FileName,document.DocumentTypeCode,document.Description,document.Tags,document.ModifiedDateUtc)),2) ContentHash,COALESCE(document.ModifiedDateUtc,document.CreatedDateUtc) SourceModifiedDateUtc,document.CreatedDateUtc SourceCreatedDateUtc FROM DMS.Document document WHERE document.IsDeleted=0) source ON target.TenantId=source.TenantId AND target.EntityTypeCode=source.EntityTypeCode AND target.EntityId=source.EntityId WHEN MATCHED AND (target.ContentHash<>source.ContentHash OR target.IsDeleted=1 OR target.SourceCreatedDateUtc IS NULL) THEN UPDATE SET ModuleCode=source.ModuleCode,Title=source.Title,ContentText=source.ContentText,Keywords=source.Keywords,ContentHash=source.ContentHash,IndexedDateUtc=SYSUTCDATETIME(),SourceModifiedDateUtc=source.SourceModifiedDateUtc,SourceCreatedDateUtc=source.SourceCreatedDateUtc,ModifiedDateUtc=SYSUTCDATETIME(),IsDeleted=0 WHEN NOT MATCHED THEN INSERT(TenantId,EntityTypeCode,EntityId,ModuleCode,Title,ContentText,Keywords,SecurityScopeJson,ContentHash,IndexedDateUtc,SourceModifiedDateUtc,SourceCreatedDateUtc,CreatedDateUtc,IsDeleted) VALUES(source.TenantId,source.EntityTypeCode,source.EntityId,source.ModuleCode,source.Title,source.ContentText,source.Keywords,N'{}',source.ContentHash,SYSUTCDATETIME(),source.SourceModifiedDateUtc,source.SourceCreatedDateUtc,SYSUTCDATETIME(),0) OUTPUT inserted.SearchDocumentId INTO @changed;
UPDATE document SET IsDeleted=1,ModifiedDateUtc=SYSUTCDATETIME() FROM AI.SearchDocument document WHERE document.IsDeleted=0 AND ((document.EntityTypeCode=N'ACCOUNT' AND NOT EXISTS(SELECT 1 FROM Client.Account source WHERE source.TenantId=document.TenantId AND source.AccountId=document.EntityId AND source.IsDeleted=0)) OR (document.EntityTypeCode=N'SUBMISSION' AND NOT EXISTS(SELECT 1 FROM Submissions.Submission source WHERE source.TenantId=document.TenantId AND source.SubmissionId=document.EntityId AND source.IsDeleted=0)) OR (document.EntityTypeCode=N'CLAIM' AND NOT EXISTS(SELECT 1 FROM Claims.Claim source WHERE source.TenantId=document.TenantId AND source.ClaimId=document.EntityId AND source.IsDeleted=0)) OR (document.EntityTypeCode=N'DOCUMENT' AND NOT EXISTS(SELECT 1 FROM DMS.Document source WHERE source.TenantId=document.TenantId AND source.DocumentId=document.EntityId AND source.IsDeleted=0)));
DELETE FROM AI.SearchPermission;
INSERT AI.SearchPermission(TenantId,SearchDocumentId,PrincipalTypeCode,PrincipalId,PermissionCode,CreatedDateUtc,IsDeleted) SELECT DISTINCT document.TenantId,document.SearchDocumentId,N'ROLE',rolePermission.RoleId,N'READ',SYSUTCDATETIME(),0 FROM AI.SearchDocument document JOIN IAM.Permission permission ON permission.PermissionCode=CASE document.ModuleCode WHEN N'Accounts' THEN N'ACCOUNT_VIEW' WHEN N'Submissions' THEN N'SUBMISSION_VIEW' WHEN N'Claims' THEN N'CLAIM_VIEW' WHEN N'Documents' THEN N'DOCUMENT_VIEW' END OR permission.PermissionCode=N'NAV_ALL' JOIN IAM.RolePermission rolePermission ON rolePermission.PermissionId=permission.PermissionId AND rolePermission.IsDeleted=0 JOIN IAM.Role role ON role.RoleId=rolePermission.RoleId AND role.TenantId=document.TenantId AND role.IsDeleted=0 WHERE document.IsDeleted=0 AND permission.IsDeleted=0;
INSERT AI.SearchPermission(TenantId,SearchDocumentId,PrincipalTypeCode,PrincipalId,PermissionCode,CreatedDateUtc,IsDeleted) SELECT document.TenantId,document.SearchDocumentId,N'USER',source.PrincipalUserId,N'READ',SYSUTCDATETIME(),0 FROM AI.SearchDocument document CROSS APPLY(SELECT CASE document.EntityTypeCode WHEN N'ACCOUNT' THEN (SELECT OwnerUserId FROM Client.Account WHERE TenantId=document.TenantId AND AccountId=document.EntityId) WHEN N'SUBMISSION' THEN (SELECT AssignedToUserId FROM Submissions.Submission WHERE TenantId=document.TenantId AND SubmissionId=document.EntityId) WHEN N'DOCUMENT' THEN (SELECT CreatedByUserId FROM DMS.Document WHERE TenantId=document.TenantId AND DocumentId=document.EntityId) END PrincipalUserId) source WHERE document.IsDeleted=0 AND source.PrincipalUserId IS NOT NULL;
DECLARE @changedCount INT=(SELECT COUNT(1) FROM @changed);
COMMIT TRANSACTION;
SELECT @changedCount;
""";
        using var connection=await connectionFactory.CreateOpenConnectionAsync(cancellationToken);return await connection.ExecuteScalarAsync<int>(new CommandDefinition(sql,cancellationToken:cancellationToken));
    }

    public async Task<int> ProcessRecommendationsAsync(string leaseOwner,IntelligenceWorkerSettings settings,CancellationToken cancellationToken)
    {
        const string leaseSql="""DECLARE @leased TABLE(Id UNIQUEIDENTIFIER);;WITH candidates AS(SELECT TOP(@BatchSize)* FROM AI.RecommendationWorkItem WITH(UPDLOCK,READPAST,ROWLOCK) WHERE IsDeleted=0 AND StatusCode IN(N'PENDING',N'RETRY') AND AvailableDateUtc<=SYSUTCDATETIME() AND (LeaseExpiresDateUtc IS NULL OR LeaseExpiresDateUtc<SYSUTCDATETIME()) ORDER BY AvailableDateUtc,CreatedDateUtc) UPDATE candidates SET StatusCode=N'PROCESSING',LeaseOwner=@LeaseOwner,LeaseExpiresDateUtc=DATEADD(SECOND,@LeaseSeconds,SYSUTCDATETIME()),AttemptCount=AttemptCount+1,ModifiedDateUtc=SYSUTCDATETIME() OUTPUT inserted.RecommendationWorkItemId INTO @leased;SELECT work.RecommendationWorkItemId,work.TenantId,work.EntityTypeCode,work.EntityId,work.CorrelationId,work.AttemptCount,work.MaximumAttempts FROM AI.RecommendationWorkItem work JOIN @leased leased ON leased.Id=work.RecommendationWorkItemId;""";
        using var connection=await connectionFactory.CreateOpenConnectionAsync(cancellationToken);var work=(await connection.QueryAsync<RecommendationWork>(new CommandDefinition(leaseSql,new{LeaseOwner=leaseOwner,settings.BatchSize,LeaseSeconds=settings.LeaseSeconds},cancellationToken:cancellationToken))).AsList();
        foreach(var item in work){try{await GenerateRecommendationsAsync(connection,item,leaseOwner,cancellationToken);}catch(Exception ex){logger.LogError(ex,"Recommendation work {WorkItemId} failed.",item.RecommendationWorkItemId);await FailRecommendationAsync(connection,item,leaseOwner,ex,cancellationToken);}}
        return work.Count;
    }

    public async Task<int> ProcessEvaluationsAsync(string leaseOwner,IntelligenceWorkerSettings settings,CancellationToken cancellationToken)
    {
        const string leaseSql="""DECLARE @leased TABLE(Id UNIQUEIDENTIFIER);;WITH candidates AS(SELECT TOP(20)* FROM AI.EvaluationRun WITH(UPDLOCK,READPAST,ROWLOCK) WHERE IsDeleted=0 AND (StatusCode=N'QUEUED' OR (StatusCode=N'PROCESSING' AND LeaseExpiresDateUtc<SYSUTCDATETIME())) ORDER BY CreatedDateUtc) UPDATE candidates SET StatusCode=N'PROCESSING',StartedDateUtc=SYSUTCDATETIME(),LeaseOwner=@LeaseOwner,LeaseExpiresDateUtc=DATEADD(SECOND,@LeaseSeconds,SYSUTCDATETIME()),ModifiedDateUtc=SYSUTCDATETIME() OUTPUT inserted.EvaluationRunId INTO @leased;SELECT run.EvaluationRunId,run.TenantId,run.WindowStartUtc,run.WindowEndUtc,definition.MetricCode,definition.CalculationCode,definition.TargetValue,definition.WarningValue,definition.MinimumSampleSize,definition.ConfigurationJson FROM AI.EvaluationRun run JOIN @leased leased ON leased.Id=run.EvaluationRunId JOIN AI.EvaluationDefinition definition ON definition.EvaluationDefinitionId=run.EvaluationDefinitionId;""";using var connection=await connectionFactory.CreateOpenConnectionAsync(cancellationToken);var runs=(await connection.QueryAsync<EvaluationWork>(new CommandDefinition(leaseSql,new{LeaseOwner=leaseOwner,LeaseSeconds=settings.LeaseSeconds},cancellationToken:cancellationToken))).AsList();foreach(var run in runs){try{await CompleteEvaluationAsync(connection,run,leaseOwner,cancellationToken);}catch(Exception ex){logger.LogError(ex,"Evaluation run {EvaluationRunId} failed.",run.EvaluationRunId);await connection.ExecuteAsync(new CommandDefinition("UPDATE AI.EvaluationRun SET StatusCode=N'FAILED',ErrorMessage=@Error,CompletedDateUtc=SYSUTCDATETIME(),LeaseOwner=NULL,LeaseExpiresDateUtc=NULL,ModifiedDateUtc=SYSUTCDATETIME() WHERE EvaluationRunId=@Id AND LeaseOwner=@LeaseOwner AND StatusCode=N'PROCESSING';",new{Id=run.EvaluationRunId,LeaseOwner=leaseOwner,Error=Truncate(ex.Message,4000)},cancellationToken:cancellationToken));}}return runs.Count;
    }

    private static async Task GenerateRecommendationsAsync(IDbConnection connection,RecommendationWork item,string leaseOwner,CancellationToken cancellationToken)
    {
        const string sql="""INSERT AI.Recommendation(TenantId,RecommendationTypeId,RecommendationRuleId,EntityTypeCode,EntityId,Title,Summary,Rationale,ActionCode,ActionPayloadJson,PriorityCode,StatusCode,Confidence,Score,ExpiresDateUtc,IdempotencyKey,CreatedDateUtc,CreatedByUserId,IsDeleted) SELECT @TenantId,type.RecommendationTypeId,rule.RecommendationRuleId,@EntityTypeCode,@EntityId,COALESCE(NULLIF(JSON_VALUE(rule.ActionJson,'$.title'),N''),rule.Name),COALESCE(NULLIF(JSON_VALUE(rule.ActionJson,'$.summary'),N''),rule.Description,rule.Name),JSON_VALUE(rule.ActionJson,'$.rationale'),JSON_VALUE(rule.ActionJson,'$.actionCode'),JSON_QUERY(rule.ActionJson,'$.payload'),type.DefaultPriorityCode,CASE WHEN type.RequiresHumanReview=1 THEN N'REVIEW_REQUIRED' ELSE N'OPEN' END,rule.MinimumConfidence,CONVERT(decimal(18,6),rule.Priority),CASE WHEN type.DefaultExpirationHours IS NULL THEN NULL ELSE DATEADD(HOUR,type.DefaultExpirationHours,SYSUTCDATETIME()) END,CONCAT(CONVERT(nvarchar(36),@WorkItemId),N':',CONVERT(nvarchar(36),rule.RecommendationRuleId)),SYSUTCDATETIME(),@CreatedByUserId,0 FROM AI.RecommendationRule rule JOIN AI.RecommendationType type ON type.RecommendationTypeId=rule.RecommendationTypeId AND type.IsActive=1 AND type.IsDeleted=0 WHERE rule.TenantId=@TenantId AND rule.EntityTypeCode=@EntityTypeCode AND rule.IsActive=1 AND rule.IsDeleted=0 AND rule.EffectiveFromUtc<=SYSUTCDATETIME() AND (rule.EffectiveToUtc IS NULL OR rule.EffectiveToUtc>SYSUTCDATETIME()) AND NOT EXISTS(SELECT 1 FROM AI.Recommendation existing WHERE existing.TenantId=@TenantId AND existing.IdempotencyKey=CONCAT(CONVERT(nvarchar(36),@WorkItemId),N':',CONVERT(nvarchar(36),rule.RecommendationRuleId)) AND existing.IsDeleted=0);INSERT AI.RecommendationEvidence(TenantId,RecommendationId,EvidenceTypeCode,SourceEntityTypeCode,SourceEntityId,Description,RelevanceScore,CreatedDateUtc,CreatedByUserId,IsDeleted) SELECT recommendation.TenantId,recommendation.RecommendationId,N'GOVERNED_RULE',N'RECOMMENDATION_RULE',recommendation.RecommendationRuleId,N'Generated from an active tenant-governed recommendation rule.',recommendation.Confidence,SYSUTCDATETIME(),@CreatedByUserId,0 FROM AI.Recommendation recommendation WHERE recommendation.TenantId=@TenantId AND recommendation.IdempotencyKey LIKE CONCAT(CONVERT(nvarchar(36),@WorkItemId),N':%') AND NOT EXISTS(SELECT 1 FROM AI.RecommendationEvidence evidence WHERE evidence.RecommendationId=recommendation.RecommendationId AND evidence.EvidenceTypeCode=N'GOVERNED_RULE' AND evidence.IsDeleted=0);INSERT AI.ReviewQueueItem(TenantId,ReviewTypeCode,SourceEntityTypeCode,SourceEntityId,Title,Summary,PriorityCode,StatusCode,Confidence,IdempotencyKey,CreatedDateUtc,CreatedByUserId,IsDeleted) SELECT recommendation.TenantId,N'RECOMMENDATION',N'RECOMMENDATION',recommendation.RecommendationId,recommendation.Title,recommendation.Summary,recommendation.PriorityCode,N'OPEN',recommendation.Confidence,CONCAT(N'RECOMMENDATION:',CONVERT(nvarchar(36),recommendation.RecommendationId)),SYSUTCDATETIME(),@CreatedByUserId,0 FROM AI.Recommendation recommendation WHERE recommendation.TenantId=@TenantId AND recommendation.IdempotencyKey LIKE CONCAT(CONVERT(nvarchar(36),@WorkItemId),N':%') AND recommendation.StatusCode=N'REVIEW_REQUIRED' AND NOT EXISTS(SELECT 1 FROM AI.ReviewQueueItem review WHERE review.TenantId=recommendation.TenantId AND review.IdempotencyKey=CONCAT(N'RECOMMENDATION:',CONVERT(nvarchar(36),recommendation.RecommendationId)) AND review.IsDeleted=0);UPDATE AI.RecommendationWorkItem SET StatusCode=N'COMPLETED',LeaseOwner=NULL,LeaseExpiresDateUtc=NULL,ModifiedDateUtc=SYSUTCDATETIME() WHERE RecommendationWorkItemId=@WorkItemId AND TenantId=@TenantId AND LeaseOwner=@LeaseOwner AND StatusCode=N'PROCESSING';""";await connection.ExecuteAsync(new CommandDefinition(sql,new{item.TenantId,item.EntityTypeCode,item.EntityId,WorkItemId=item.RecommendationWorkItemId,CreatedByUserId=(Guid?)null,LeaseOwner=leaseOwner},cancellationToken:cancellationToken));
    }

    private static Task FailRecommendationAsync(IDbConnection connection,RecommendationWork item,string leaseOwner,Exception exception,CancellationToken cancellationToken)=>connection.ExecuteAsync(new CommandDefinition("UPDATE AI.RecommendationWorkItem SET StatusCode=CASE WHEN AttemptCount>=MaximumAttempts THEN N'DEAD_LETTER' ELSE N'RETRY' END,AvailableDateUtc=DATEADD(SECOND,POWER(2,CASE WHEN AttemptCount>8 THEN 8 ELSE AttemptCount END)*15,SYSUTCDATETIME()),LeaseOwner=NULL,LeaseExpiresDateUtc=NULL,LastErrorMessage=@Error,ModifiedDateUtc=SYSUTCDATETIME() WHERE RecommendationWorkItemId=@Id AND TenantId=@TenantId AND LeaseOwner=@LeaseOwner AND StatusCode=N'PROCESSING';",new{Id=item.RecommendationWorkItemId,item.TenantId,LeaseOwner=leaseOwner,Error=Truncate(exception.Message,4000)},cancellationToken:cancellationToken));

    private static async Task CompleteEvaluationAsync(IDbConnection connection,EvaluationWork work,string leaseOwner,CancellationToken cancellationToken)
    {
        var (count,value)=work.CalculationCode.ToUpperInvariant() switch
        {
            "SUCCESS_RATE"=>await ScalarAsync(connection,work,"SELECT COUNT(1) Count,AVG(CONVERT(decimal(18,6),CASE WHEN StatusCode=N'COMPLETED' THEN 1.0 ELSE 0 END)) Value FROM AI.Execution WHERE (TenantId=@TenantId OR @TenantId IS NULL) AND IsDeleted=0 AND StartedDateUtc>=@Start AND StartedDateUtc<@End",cancellationToken),
            "AVERAGE_CONFIDENCE"=>await ScalarAsync(connection,work,"SELECT COUNT(Confidence) Count,AVG(CONVERT(decimal(18,6),Confidence)) Value FROM AI.Execution WHERE (TenantId=@TenantId OR @TenantId IS NULL) AND IsDeleted=0 AND StartedDateUtc>=@Start AND StartedDateUtc<@End",cancellationToken),
            "AVERAGE_DURATION_MS"=>await ScalarAsync(connection,work,"SELECT COUNT(DurationMilliseconds) Count,AVG(CONVERT(decimal(18,6),DurationMilliseconds)) Value FROM AI.Execution WHERE (TenantId=@TenantId OR @TenantId IS NULL) AND IsDeleted=0 AND StartedDateUtc>=@Start AND StartedDateUtc<@End",cancellationToken),
            "CORRECTION_RATE"=>await ScalarAsync(connection,work,"SELECT COUNT(1) Count,AVG(CONVERT(decimal(18,6),CASE WHEN feedback.CorrectionReference IS NOT NULL THEN 1.0 ELSE 0 END)) Value FROM AI.ExecutionFeedback feedback JOIN AI.Execution execution ON execution.ExecutionId=feedback.ExecutionId WHERE (feedback.TenantId=@TenantId OR @TenantId IS NULL) AND feedback.IsDeleted=0 AND execution.StartedDateUtc>=@Start AND execution.StartedDateUtc<@End",cancellationToken),
            _=>throw new InvalidOperationException($"Unsupported database evaluation calculation code '{work.CalculationCode}'.")
        };
        var direction=ParseDirection(work.ConfigurationJson);var passed=count>=work.MinimumSampleSize&&(value.HasValue&&(direction=="LOWER_IS_BETTER"?value<=work.TargetValue:value>=work.TargetValue));var status=count<work.MinimumSampleSize?"INSUFFICIENT_DATA":passed?"PASSED":"FAILED";var details=JsonSerializer.Serialize(new{work.MetricCode,direction,work.TargetValue,work.WarningValue,work.MinimumSampleSize});await connection.ExecuteAsync(new CommandDefinition("UPDATE AI.EvaluationRun SET StatusCode=@StatusCode,SampleCount=@SampleCount,MetricValue=@MetricValue,Passed=@Passed,DetailsJson=@Details,CompletedDateUtc=SYSUTCDATETIME(),LeaseOwner=NULL,LeaseExpiresDateUtc=NULL,ModifiedDateUtc=SYSUTCDATETIME() WHERE EvaluationRunId=@Id AND LeaseOwner=@LeaseOwner AND StatusCode=N'PROCESSING';",new{Id=work.EvaluationRunId,LeaseOwner=leaseOwner,StatusCode=status,SampleCount=count,MetricValue=value,Passed=count>=work.MinimumSampleSize?(bool?)passed:null,Details=details},cancellationToken:cancellationToken));
    }

    private static async Task<(int Count,decimal? Value)> ScalarAsync(IDbConnection connection,EvaluationWork work,string sql,CancellationToken cancellationToken){var result=await connection.QuerySingleAsync<MetricResult>(new CommandDefinition(sql,new{work.TenantId,Start=work.WindowStartUtc,End=work.WindowEndUtc},cancellationToken:cancellationToken));return(result.Count,result.Value);}
    private static string ParseDirection(string? json){if(string.IsNullOrWhiteSpace(json))return "HIGHER_IS_BETTER";using var document=JsonDocument.Parse(json);return document.RootElement.TryGetProperty("direction",out var node)?node.GetString()?.ToUpperInvariant()??"HIGHER_IS_BETTER":"HIGHER_IS_BETTER";}
    private static string Truncate(string value,int max)=>value.Length<=max?value:value[..max];
    private sealed record SettingRow(string SettingKey,string SettingValue);
    private sealed record RecommendationWork(Guid RecommendationWorkItemId,Guid TenantId,string EntityTypeCode,Guid EntityId,string CorrelationId,int AttemptCount,int MaximumAttempts);
    private sealed record EvaluationWork(Guid EvaluationRunId,Guid? TenantId,DateTime WindowStartUtc,DateTime WindowEndUtc,string MetricCode,string CalculationCode,decimal TargetValue,decimal WarningValue,int MinimumSampleSize,string? ConfigurationJson);
    private sealed record MetricResult(int Count,decimal? Value);
}

public sealed record IntelligenceWorkerSettings(int BatchSize,int PollIntervalSeconds,int LeaseSeconds,int EvaluationIntervalMinutes,int SearchIndexIntervalMinutes);
